-- Three separate trigger functions for INSERT, UPDATE, DELETE
CREATE OR REPLACE FUNCTION trg_products_history_insert() RETURNS TRIGGER AS $$ BEGIN
    INSERT INTO producthistory (productid, action, newprice, newstock, modifiedby) VALUES (NEW.productid, 'INSERT', NEW.price, NEW.stockquantity, current_user);
    RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_products_history_after_insert AFTER INSERT ON products FOR EACH ROW EXECUTE FUNCTION trg_products_history_insert();

CREATE OR REPLACE FUNCTION trg_products_history_update() RETURNS TRIGGER AS $$ BEGIN
    IF OLD.price <> NEW.price OR OLD.stockquantity <> NEW.stockquantity THEN
        INSERT INTO producthistory (productid, action, oldprice, newprice, oldstock, newstock, modifiedby) VALUES (NEW.productid, 'UPDATE', OLD.price, NEW.price, OLD.stockquantity, NEW.stockquantity, current_user);
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_products_history_after_update AFTER UPDATE ON products FOR EACH ROW EXECUTE FUNCTION trg_products_history_update();

CREATE OR REPLACE FUNCTION trg_products_history_delete() RETURNS TRIGGER AS $$ BEGIN
    INSERT INTO producthistory (productid, action, oldprice, oldstock, modifiedby) VALUES (OLD.productid, 'DELETE', OLD.price, OLD.stockquantity, current_user);
    RETURN OLD;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_products_history_after_delete AFTER DELETE ON products FOR EACH ROW EXECUTE FUNCTION trg_products_history_delete();
